begin;
select set_config('opportunityos.expiry_u',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('opportunityos.expiry_u')::uuid,'expiry-'||current_setting('opportunityos.expiry_u')||'@example.invalid');
insert into public.profiles(user_id) values(current_setting('opportunityos.expiry_u')::uuid);
insert into public.opportunities(user_id,fingerprint,title,deadline,type,extracted_json,extraction_confidence,extraction_version) values(current_setting('opportunityos.expiry_u')::uuid,repeat('c',64),'DEMO Expiry',current_date+7,'internship','{}',.9,'extract-v1');
update public.matches set status='complete',decision='ASK',eligibility_status='ELIGIBLE',evaluation_day=(now() at time zone 'Asia/Kolkata')::date,explanation='DEMO expiry test' where user_id=current_setting('opportunityos.expiry_u')::uuid;
select set_config('opportunityos.expiry_a',(public.worker_create_approval((select id from public.matches where user_id=current_setting('opportunityos.expiry_u')::uuid),'99999020','http://localhost:5678/webhook-waiting/99999020?signature='||repeat('a',64))->>'approval_id'),true);
update public.approvals set expires_at=now()-interval '1 second' where id=current_setting('opportunityos.expiry_a')::uuid;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('opportunityos.expiry_u'))::text,true);
do $$ declare r jsonb;begin r:=public.confirm_approval(current_setting('opportunityos.expiry_a')::uuid,1,'approved','Expired test');if r->>'reason'<>'EXPIRED' then raise exception 'Expired approval accepted';end if;if exists(select 1 from public.applications where user_id=current_setting('opportunityos.expiry_u')::uuid) then raise exception 'Expired approval performed actions';end if;end;$$;
reset role;
update public.matches set revision=revision+1 where user_id=current_setting('opportunityos.expiry_u')::uuid;
select set_config('opportunityos.expiry_a',(public.worker_create_approval((select id from public.matches where user_id=current_setting('opportunityos.expiry_u')::uuid),'99999021','http://localhost:5678/webhook-waiting/99999021?signature='||repeat('b',64))->>'approval_id'),true);
update public.matches set revision=revision+1 where user_id=current_setting('opportunityos.expiry_u')::uuid;
set local role authenticated;
do $$ declare r jsonb;begin r:=public.confirm_approval(current_setting('opportunityos.expiry_a')::uuid,2,'approved','Stale test');if r->>'reason'<>'STALE' then raise exception 'Stale approval accepted';end if;end;$$;
reset role;
rollback;
select 'PASS: expired and stale reviews never authorize actions' as test_result;
